const items = $input.all();
return items.map((item, index) => ({
  json: { ...item.json, kolejnoscWTrasie: index + 1 }
}));

const items = $input.all();
if (items.length === 0) {
  return [{ json: { message: '📋 Plan montażu na dzisiaj:\n\nBrak zaplanowanych zleceń.' } }];
}
let message = '📋 Plan montażu na ' + new Date().toLocaleDateString('pl-PL') + ':\n\n';
items.forEach((item) => {
  const job = item.json;
  message += job.kolejnoscWTrasie + '. ' + (job['Imie i nazwisko'] || 'Brak danych') + '\n';
  message += '   Adres: ' + (job['Adres Zamieszkania'] || '') + ' (' + (job['Kod pocztowy'] || '') + ')\n';
  message += '   Usługa: ' + (job['Typ Usługi'] || '') + '\n';
  message += '   Priorytet: ' + (job['Priorytet'] || 'Normalny') + '\n';
  message += '   Mapa: ' + (job['Link do Mapy'] || 'brak') + '\n\n';
});
message += '✅ Powodzenia w realizacji zleceń!';
return [{ json: { message } }];

const content = $input.item.json.message.content;
let parsed;
try {
  parsed = JSON.parse(content);
} catch(e) {
  parsed = { imieNazwisko: '', adresZamieszkania: '', kodPocztowy: '', typUslugi: '' };
}
return [{
  json: {
    imieNazwisko: parsed.imieNazwisko || '',
    adresZamieszkania: parsed.adresZamieszkania || '',
    kodPocztowy: parsed.kodPocztowy || '',
    typUslugi: parsed.typUslugi || '',
    zrodlo: 'Mail - Salon',
    dataZgloszenia: new Date().toISOString().split('T')[0]
  }
}];
